True def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]
    for r, c in points:
        # A marker is the center of a small open-sided frame; its lower edge
        # continues across the whole grid as a separator.
        for x in range(c - 2, c + 3):
            if 0 <= r - 2 < h and 0 <= x < w:
                out[r - 2][x] = 5
        for y in (r - 1, r, r + 1):
            if 0 <= y < h:
                for x in (c - 2, c + 2):
                    if 0 <= x < w:
                        out[y][x] = 2
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 3
        if 0 <= r + 2 < h:
            out[r + 2] = [2] * w
            for x in range(c - 2, c + 3):
                if 0 <= x < w:
                    out[r + 2][x] = 8
    return out
